    {d₀ : ∀ k, C (k + 1) →ₗ[ZMod 2] C k} {d₁ : ∀ k, D (k + 1) →ₗ[ZMod 2] D k}
    {Φ : ∀ k, C k →ₗ[ZMod 2] D k}
    (h : ∀ k, (coneDiff d₀ d₁ Φ k).comp (coneDiff d₀ d₁ Φ (k + 1)) = 0) (k : ℕ)
